const ICONS_557 = RAW_ICONS.map(([id, name, label, theme, path]) => ({
    id,
    name,
    label,
    theme,
    path,
    svg: path
}));

// Backward compatibility alias for 256 / 551
const ICONS_256 = ICONS_557.slice(0, 256);
const ICONS_551 = ICONS_557.slice(0, 551);
const ICONS = ICONS_557;

const ICONS_BY_ID = new Map(ICONS_557.map(ic => [ic.id, ic]));
const ICONS_BY_NAME = new Map(ICONS_557.map(ic => [ic.name.toLowerCase(), ic]));

// Add helpful aliases
ICONS_BY_NAME.set('overlay', ICONS_BY_ID.get(555));
ICONS_BY_NAME.set('layer', ICONS_BY_ID.get(556));
ICONS_BY_NAME.set('layers', ICONS_BY_ID.get(556));

function getIcon(opcodeOrName) {
    if (typeof opcodeOrName === 'number') {
        const id = Math.floor(opcodeOrName);
        return ICONS_BY_ID.get(id) || ICONS_557[0];
    }
    const key = String(opcodeOrName || '').toLowerCase().trim();
    if (/^\d+$/.test(key)) {
        return ICONS_BY_ID.get(parseInt(key, 10)) || ICONS_557[0];
    }
    return ICONS_BY_NAME.get(key) || ICONS_557[0];
}

module.exports = {
    ICONS,
    ICONS_557,
    ICONS_551,
    ICONS_256,
    RAW_ICONS,
    TOTAL_ICONS: 557,
    getIcon
};
